"""The intermediate document model produced by the parser.

Everything here is already style-resolved: the layout engine never has to look
at a style sheet again.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import List, Optional

from .props import CellProps, ParaProps, RowProps, RunProps, TableProps


@dataclass
class Link:
    url: Optional[str] = None
    anchor: Optional[str] = None
    tooltip: Optional[str] = None


@dataclass
class Inline:
    props: RunProps = field(default_factory=RunProps)
    link: Optional[Link] = None


@dataclass
class TextRun(Inline):
    text: str = ''


@dataclass
class TabRun(Inline):
    pass


@dataclass
class BreakRun(Inline):
    kind: str = 'line'          # line | page | column
    clear: Optional[str] = None


@dataclass
class ImageRun(Inline):
    data: Optional[bytes] = None
    width: float = 0.0          # points
    height: float = 0.0
    alt: str = ''
    rotation: float = 0.0
    fmt: str = ''
    crop: Optional[tuple] = None   # (left, top, right, bottom) fractions


@dataclass
class ShapeRun(Inline):
    """A drawing we cannot render faithfully; kept so its text is not lost."""
    width: float = 0.0
    height: float = 0.0
    fill: Optional[str] = None
    stroke: Optional[str] = None
    blocks: list = field(default_factory=list)


@dataclass
class FieldRun(Inline):
    kind: str = ''              # PAGE | NUMPAGES | DATE | TIME | REF | ...
    text: str = ''              # cached result from the document
    argument: str = ''
    fmt: str = ''


@dataclass
class NoteRun(Inline):
    """A footnote or endnote reference."""
    note_id: str = ''
    kind: str = 'footnote'
    mark: str = ''


@dataclass
class NumberLabel:
    text: str = ''
    props: RunProps = field(default_factory=RunProps)
    suffix: str = 'tab'
    align: str = 'left'
    font_family: Optional[str] = None


@dataclass
class FloatingObject:
    """An anchored drawing: positioned absolutely, outside the text flow."""
    image: Optional[ImageRun] = None
    blocks: list = field(default_factory=list)
    width: float = 0.0
    height: float = 0.0
    h_relative: str = 'column'
    v_relative: str = 'paragraph'
    h_offset: float = 0.0
    v_offset: float = 0.0
    h_align: Optional[str] = None
    v_align: Optional[str] = None
    behind: bool = False
    wrap: str = 'none'
    z_index: int = 0
    fill: Optional[str] = None
    stroke: Optional[str] = None
    stroke_width: float = 0.0
    rotation: float = 0.0
    alt: str = ''


@dataclass
class Block:
    pass


@dataclass
class Paragraph(Block):
    props: ParaProps = field(default_factory=ParaProps)
    items: List[Inline] = field(default_factory=list)
    mark_props: RunProps = field(default_factory=RunProps)
    number: Optional[NumberLabel] = None
    style_id: Optional[str] = None
    bookmarks: List[str] = field(default_factory=list)
    in_table: bool = False
    floats: List[FloatingObject] = field(default_factory=list)

    @property
    def text(self) -> str:
        return ''.join(i.text for i in self.items if isinstance(i, TextRun))


@dataclass
class Cell:
    blocks: List[Block] = field(default_factory=list)
    props: CellProps = field(default_factory=CellProps)
    grid_span: int = 1
    v_merge: Optional[str] = None
    width: Optional[float] = None
    column: int = 0


@dataclass
class Row:
    cells: List[Cell] = field(default_factory=list)
    props: RowProps = field(default_factory=RowProps)
    header: bool = False


@dataclass
class Table(Block):
    rows: List[Row] = field(default_factory=list)
    grid: List[float] = field(default_factory=list)
    props: TableProps = field(default_factory=TableProps)
    style_id: Optional[str] = None
    look: dict = field(default_factory=dict)
    nesting: int = 0


@dataclass
class HeaderFooter:
    blocks: List[Block] = field(default_factory=list)
    part: str = ''


@dataclass
class Section:
    width: float = 612.0
    height: float = 792.0
    margin_top: float = 72.0
    margin_right: float = 72.0
    margin_bottom: float = 72.0
    margin_left: float = 72.0
    header_distance: float = 36.0
    footer_distance: float = 36.0
    gutter: float = 0.0
    landscape: bool = False
    columns: int = 1
    column_space: float = 36.0
    column_widths: Optional[list] = None
    column_separator: bool = False
    page_num_start: Optional[int] = None
    page_num_format: Optional[str] = None
    title_page: bool = False
    vertical_align: str = 'top'
    break_type: str = 'nextPage'
    blocks: List[Block] = field(default_factory=list)
    headers: dict = field(default_factory=dict)   # default|first|even -> HeaderFooter
    footers: dict = field(default_factory=dict)
    borders: Optional[dict] = None

    @property
    def content_width(self) -> float:
        return max(1.0, self.width - self.margin_left - self.margin_right - self.gutter)

    @property
    def content_height(self) -> float:
        return max(1.0, self.height - self.margin_top - self.margin_bottom)

    def column_layout(self):
        """(x_offset, width) for each column, relative to the text area."""
        if self.column_widths:
            out = []
            x = 0.0
            for width, space in self.column_widths:
                out.append((x, width))
                x += width + space
            return out
        count = max(1, self.columns)
        total = self.content_width
        width = (total - self.column_space * (count - 1)) / count
        return [(i * (width + self.column_space), width) for i in range(count)]


@dataclass
class Document:
    sections: List[Section] = field(default_factory=list)
    styles: object = None
    numbering: object = None
    theme: object = None
    package: object = None
    settings: dict = field(default_factory=dict)
    footnotes: dict = field(default_factory=dict)
    endnotes: dict = field(default_factory=dict)
    properties: dict = field(default_factory=dict)
    warnings: List[str] = field(default_factory=list)

    @property
    def default_tab(self) -> float:
        return self.settings.get('default_tab', 36.0)

    def iter_blocks(self):
        for section in self.sections:
            for block in section.blocks:
                yield section, block
